/**
 * CoolProp TypeScript Usage Examples
 * 
 * Comprehensive examples demonstrating how to use the CoolProp WASM module
 * with TypeScript for type-safe thermodynamic calculations.
 * 
 * @version 6.6.0
 * @author CoolProp Team
 */

import CoolPropModule, { 
    CoolPropModule as ICoolPropModule,
    AbstractState, 
    Parameters, 
    InputPairs, 
    Phases,
    PhaseEnvelopeData
} from '../coolprop';
import { 
    TypeSafeWrappers, 
    MixtureUtils, 
    CoolPropUtils, 
    CoolPropError 
} from '../coolprop-wrappers';

/**
 * Initialize CoolProp module
 */
async function initializeCoolProp(): Promise<ICoolPropModule> {
    console.log('Loading CoolProp WASM module...');
    const coolprop = await CoolPropModule();
    console.log('CoolProp WASM module loaded successfully');
    return coolprop;
}

/**
 * Example 1: Basic property calculations with type safety
 */
async function basicPropertyCalculations() {
    console.log('\n=== Example 1: Basic Property Calculations ===');
    
    const coolprop = await initializeCoolProp();
    const wrappers = new TypeSafeWrappers(coolprop);
    
    try {
        // Create state for water
        const state = wrappers.createState('HEOS', 'Water');
        
        // Set state to 300 K, 1 atm
        wrappers.updateState(state, InputPairs.PT_INPUTS, 101325, 300);
        
        // Get properties with type safety
        const temperature = wrappers.getProperty(state, Parameters.iT);
        const pressure = wrappers.getProperty(state, Parameters.iP);
        const density = wrappers.getProperty(state, Parameters.iDmolar);
        const enthalpy = wrappers.getProperty(state, Parameters.iHmolar);
        const entropy = wrappers.getProperty(state, Parameters.iSmolar);
        
        console.log(`Temperature: ${temperature} K`);
        console.log(`Pressure: ${pressure} Pa`);
        console.log(`Molar density: ${density} mol/m³`);
        console.log(`Molar enthalpy: ${enthalpy} J/mol`);
        console.log(`Molar entropy: ${entropy} J/mol/K`);
        
        // Get phase information
        const phase = state.phase();
        console.log(`Phase: ${Phases[phase]}`);
        
    } catch (error) {
        if (error instanceof CoolPropError) {
            console.error(`CoolProp Error: ${error.message}`);
            console.error(`Details: ${error.getDetails()}`);
        } else {
            console.error(`Unexpected error: ${error.message}`);
        }
    }
}

/**
 * Example 2: Derivative calculations
 */
async function derivativeCalculations() {
    console.log('\n=== Example 2: Derivative Calculations ===');
    
    const coolprop = await initializeCoolProp();
    const wrappers = new TypeSafeWrappers(coolprop);
    
    try {
        const state = wrappers.createState('HEOS', 'CO2');
        wrappers.updateState(state, InputPairs.PT_INPUTS, 5000000, 350); // 50 bar, 350 K
        
        // Calculate various derivatives
        const dP_dT_rho = wrappers.getDerivative(
            state, 
            Parameters.iP, 
            Parameters.iT, 
            Parameters.iDmolar
        );
        
        const dH_dT_p = wrappers.getDerivative(
            state, 
            Parameters.iHmolar, 
            Parameters.iT, 
            Parameters.iP
        );
        
        const dS_dP_T = wrappers.getDerivative(
            state, 
            Parameters.iSmolar, 
            Parameters.iP, 
            Parameters.iT
        );
        
        console.log(`dP/dT|ρ = ${dP_dT_rho} Pa/K`);
        console.log(`dH/dT|p = ${dH_dT_p} J/mol/K (should equal Cp)`);
        console.log(`dS/dP|T = ${dS_dP_T} J/mol/K/Pa`);
        
        // Verify that dH/dT|p equals Cp
        const cp = wrappers.getProperty(state, Parameters.iCpmolar);
        console.log(`Cp = ${cp} J/mol/K`);
        console.log(`Difference: ${Math.abs(dH_dT_p - cp)} J/mol/K`);
        
    } catch (error) {
        if (error instanceof CoolPropError) {
            console.error(`CoolProp Error: ${error.message}`);
        } else {
            console.error(`Unexpected error: ${error.message}`);
        }
    }
}

/**
 * Example 3: Mixture calculations with type safety
 */
async function mixtureCalculations() {
    console.log('\n=== Example 3: Mixture Calculations ===');
    
    const coolprop = await initializeCoolProp();
    const wrappers = new TypeSafeWrappers(coolprop);
    const mixtureUtils = new MixtureUtils(coolprop);
    
    try {
        // Create mixture specification
        const mixtureSpec = {
            components: [
                { name: 'Methane', mole_fraction: 0.7 },
                { name: 'Ethane', mole_fraction: 0.2 },
                { name: 'Propane', mole_fraction: 0.1 }
            ],
            backend: 'HEOS'
        };
        
        // Validate and create mixture
        const validation = mixtureUtils.validateMixture(mixtureSpec);
        if (!validation.valid) {
            throw new Error(`Invalid mixture: ${validation.errors.join(', ')}`);
        }
        
        const state = mixtureUtils.createMixture(mixtureSpec);
        
        // Set state conditions
        wrappers.updateState(state, InputPairs.PT_INPUTS, 2000000, 250); // 20 bar, 250 K
        
        // Get mixture properties
        const density = wrappers.getProperty(state, Parameters.iDmolar);
        const enthalpy = wrappers.getProperty(state, Parameters.iHmolar);
        const compressibility = state.compressibility_factor();
        
        console.log(`Mixture density: ${density} mol/m³`);
        console.log(`Mixture enthalpy: ${enthalpy} J/mol`);
        console.log(`Compressibility factor: ${compressibility}`);
        
        // Get composition information
        const moleFractions = state.get_mole_fractions();
        const fluidNames = state.fluid_names();
        
        console.log('Composition:');
        for (let i = 0; i < fluidNames.length; i++) {
            console.log(`  ${fluidNames[i]}: ${moleFractions[i].toFixed(4)} mol/mol`);
        }
        
    } catch (error) {
        if (error instanceof CoolPropError) {
            console.error(`CoolProp Error: ${error.message}`);
        } else {
            console.error(`Unexpected error: ${error.message}`);
        }
    }
}

/**
 * Example 4: Phase envelope calculations
 */
async function phaseEnvelopeCalculations() {
    console.log('\n=== Example 4: Phase Envelope Calculations ===');
    
    const coolprop = await initializeCoolProp();
    const wrappers = new TypeSafeWrappers(coolprop);
    
    try {
        // Create binary mixture
        const state = wrappers.createState('HEOS', 'Methane&Ethane');
        wrappers.setMixture(state, [0.5, 0.5]); // 50-50 mixture
        
        // Build phase envelope
        const phaseEnvelope = wrappers.buildPhaseEnvelope(state, 'PX');
        
        console.log(`Phase envelope calculated with ${phaseEnvelope.T.length} points`);
        console.log(`Temperature range: ${Math.min(...phaseEnvelope.T).toFixed(2)} - ${Math.max(...phaseEnvelope.T).toFixed(2)} K`);
        console.log(`Pressure range: ${Math.min(...phaseEnvelope.p).toFixed(0)} - ${Math.max(...phaseEnvelope.p).toFixed(0)} Pa`);
        
        // Find critical point (approximate)
        const maxPressureIndex = phaseEnvelope.p.indexOf(Math.max(...phaseEnvelope.p));
        const criticalT = phaseEnvelope.T[maxPressureIndex];
        const criticalP = phaseEnvelope.p[maxPressureIndex];
        
        console.log(`Approximate critical point: T = ${criticalT.toFixed(2)} K, P = ${criticalP.toFixed(0)} Pa`);
        
    } catch (error) {
        if (error instanceof CoolPropError) {
            console.error(`CoolProp Error: ${error.message}`);
        } else {
            console.error(`Unexpected error: ${error.message}`);
        }
    }
}

/**
 * Example 5: Critical and limiting properties
 */
async function criticalAndLimitingProperties() {
    console.log('\n=== Example 5: Critical and Limiting Properties ===');
    
    const coolprop = await initializeCoolProp();
    const wrappers = new TypeSafeWrappers(coolprop);
    
    try {
        const fluids = ['Water', 'CO2', 'Nitrogen', 'Propane'];
        
        for (const fluid of fluids) {
            console.log(`\n${fluid}:`);
            
            const state = wrappers.createState('HEOS', fluid);
            
            // Get critical properties
            const criticalProps = wrappers.getCriticalProperties(state);
            console.log(`  Critical T: ${criticalProps.temperature.toFixed(2)} K`);
            console.log(`  Critical P: ${(criticalProps.pressure / 1e6).toFixed(3)} MPa`);
            console.log(`  Critical ρ: ${criticalProps.density.toFixed(2)} mol/m³`);
            
            // Get limiting properties
            try {
                const Tmin = state.Tmin();
                const Tmax = state.Tmax();
                const pmax = state.pmax();
                
                console.log(`  T range: ${Tmin.toFixed(2)} - ${Tmax.toFixed(2)} K`);
                console.log(`  Max P: ${(pmax / 1e6).toFixed(1)} MPa`);
            } catch {
                console.log('  Limiting properties not available');
            }
            
            // Get molecular properties
            try {
                const molarMass = state.molar_mass();
                const acentricFactor = state.acentric_factor();
                
                console.log(`  Molar mass: ${(molarMass * 1000).toFixed(3)} g/mol`);
                console.log(`  Acentric factor: ${acentricFactor.toFixed(4)}`);
            } catch {
                console.log('  Molecular properties not available');
            }
        }
        
    } catch (error) {
        if (error instanceof CoolPropError) {
            console.error(`CoolProp Error: ${error.message}`);
        } else {
            console.error(`Unexpected error: ${error.message}`);
        }
    }
}

/**
 * Example 6: Saturation calculations and two-phase properties
 */
async function saturationCalculations() {
    console.log('\n=== Example 6: Saturation Calculations ===');
    
    const coolprop = await initializeCoolProp();
    const wrappers = new TypeSafeWrappers(coolprop);
    
    try {
        const state = wrappers.createState('HEOS', 'Water');
        
        // Calculate saturation properties at different temperatures
        const temperatures = [300, 350, 400, 450, 500]; // K
        
        console.log('Temperature [K] | Sat. Pressure [bar] | Liquid Density [kg/m³] | Vapor Density [kg/m³]');
        console.log('----------------|---------------------|------------------------|---------------------');
        
        for (const T of temperatures) {
            // Set saturated liquid state
            wrappers.updateState(state, InputPairs.QT_INPUTS, 0, T);
            
            const pSat = wrappers.getProperty(state, Parameters.iP);
            const rhoLiq = wrappers.getProperty(state, Parameters.iDmass);
            
            // Set saturated vapor state
            wrappers.updateState(state, InputPairs.QT_INPUTS, 1, T);
            const rhoVap = wrappers.getProperty(state, Parameters.iDmass);
            
            console.log(`${T.toString().padStart(15)} | ${(pSat/1e5).toFixed(3).padStart(19)} | ${rhoLiq.toFixed(1).padStart(22)} | ${rhoVap.toFixed(3).padStart(19)}`);
        }
        
        // Two-phase mixture properties
        console.log('\nTwo-phase mixture at 100°C:');
        const qualities = [0, 0.25, 0.5, 0.75, 1.0];
        
        console.log('Quality [-] | Density [kg/m³] | Enthalpy [kJ/kg] | Entropy [kJ/kg/K]');
        console.log('-----------|-----------------|------------------|------------------');
        
        for (const Q of qualities) {
            wrappers.updateState(state, InputPairs.QT_INPUTS, Q, 373.15);
            
            const density = wrappers.getProperty(state, Parameters.iDmass);
            const enthalpy = wrappers.getProperty(state, Parameters.iHmass) / 1000; // kJ/kg
            const entropy = wrappers.getProperty(state, Parameters.iSmass) / 1000; // kJ/kg/K
            
            console.log(`${Q.toFixed(2).padStart(10)} | ${density.toFixed(2).padStart(15)} | ${enthalpy.toFixed(1).padStart(16)} | ${entropy.toFixed(4).padStart(16)}`);
        }
        
    } catch (error) {
        if (error instanceof CoolPropError) {
            console.error(`CoolProp Error: ${error.message}`);
        } else {
            console.error(`Unexpected error: ${error.message}`);
        }
    }
}

/**
 * Example 7: Unit conversions and utility functions
 */
async function unitConversionsAndUtilities() {
    console.log('\n=== Example 7: Unit Conversions and Utilities ===');
    
    try {
        // Temperature conversions
        const tempF = 68; // °F
        const tempK = CoolPropUtils.fahrenheitToKelvin(tempF);
        const tempC = CoolPropUtils.kelvinToCelsius(tempK);
        
        console.log(`${tempF}°F = ${tempK}K = ${tempC}°C`);
        
        // Pressure conversions
        const pressureBar = 10; // bar
        const pressurePa = CoolPropUtils.barToPascal(pressureBar);
        const pressurePsi = CoolPropUtils.pascalToPsi(pressurePa);
        
        console.log(`${pressureBar} bar = ${pressurePa} Pa = ${pressurePsi.toFixed(2)} psi`);
        
        // Input validation examples
        console.log('\nInput validation:');
        console.log(`Is 300K valid temperature? ${CoolPropUtils.isValidTemperature(300)}`);
        console.log(`Is -10K valid temperature? ${CoolPropUtils.isValidTemperature(-10)}`);
        console.log(`Is 1e6 Pa valid pressure? ${CoolPropUtils.isValidPressure(1e6)}`);
        console.log(`Is -1000 Pa valid pressure? ${CoolPropUtils.isValidPressure(-1000)}`);
        
    } catch (error) {
        console.error(`Error in utility functions: ${error.message}`);
    }
}

/**
 * Example 8: Error handling and state validation
 */
async function errorHandlingAndValidation() {
    console.log('\n=== Example 8: Error Handling and State Validation ===');
    
    const coolprop = await initializeCoolProp();
    const wrappers = new TypeSafeWrappers(coolprop);
    
    try {
        const state = wrappers.createState('HEOS', 'Water');
        
        // Valid state
        wrappers.updateState(state, InputPairs.PT_INPUTS, 101325, 300);
        let validation = wrappers.validateState(state);
        console.log(`Valid state: ${validation.valid}, Phase: ${Phases[validation.phase]}`);
        if (validation.warnings.length > 0) {
            console.log(`Warnings: ${validation.warnings.join(', ')}`);
        }
        
        // Try invalid state (very high temperature)
        try {
            wrappers.updateState(state, InputPairs.PT_INPUTS, 101325, 5000);
            validation = wrappers.validateState(state);
            console.log(`High temperature state: ${validation.valid}`);
            if (validation.warnings.length > 0) {
                console.log(`Warnings: ${validation.warnings.join(', ')}`);
            }
        } catch (error) {
            if (error instanceof CoolPropError) {
                console.log(`Expected error for high temperature: ${error.message}`);
            }
        }
        
        // Try invalid backend
        try {
            wrappers.createState('INVALID_BACKEND', 'Water');
        } catch (error) {
            if (error instanceof CoolPropError) {
                console.log(`Expected error for invalid backend: ${error.message}`);
            }
        }
        
        // Try invalid fluid
        try {
            wrappers.createState('HEOS', 'NonExistentFluid');
        } catch (error) {
            if (error instanceof CoolPropError) {
                console.log(`Expected error for invalid fluid: ${error.message}`);
            }
        }
        
    } catch (error) {
        if (error instanceof CoolPropError) {
            console.error(`CoolProp Error: ${error.message}`);
            console.error(`Details: ${error.getDetails()}`);
        } else {
            console.error(`Unexpected error: ${error.message}`);
        }
    }
}

/**
 * Main function to run all examples
 */
async function runAllExamples() {
    console.log('CoolProp TypeScript Examples');
    console.log('============================');
    
    try {
        await basicPropertyCalculations();
        await derivativeCalculations();
        await mixtureCalculations();
        await phaseEnvelopeCalculations();
        await criticalAndLimitingProperties();
        await saturationCalculations();
        await unitConversionsAndUtilities();
        await errorHandlingAndValidation();
        
        console.log('\n✅ All examples completed successfully!');
        
    } catch (error) {
        console.error('\n❌ Example execution failed:', error.message);
        process.exit(1);
    }
}

// Run examples if this file is executed directly
if (require.main === module) {
    runAllExamples().catch(console.error);
}

export {
    basicPropertyCalculations,
    derivativeCalculations,
    mixtureCalculations,
    phaseEnvelopeCalculations,
    criticalAndLimitingProperties,
    saturationCalculations,
    unitConversionsAndUtilities,
    errorHandlingAndValidation,
    runAllExamples
};